use system.collections.list

fn square_all(items List<int>) List<int>
    var out = List<int>()
    for item in items
        out.push(item * item)
    out

fn main()
    let numbers = List([1, 2, 3, 4])
    let squares = square_all(numbers)
    var total = 0
    for s in squares
        total = total + s
    println(f"squares {squares.length()} total {total}")

